2	 * Reimplementation of `argparse.ArgumentParser`, covering the behaviours this
3	 * program can reach.
4	 *
5	 * Parsing follows CPython's two-phase design: every token is first classified
6	 * into a pattern string ('O' option, 'A' positional-ish, '-' for a bare `--`),
7	 * and actions then consume slices of that pattern. Reproducing this structure
8	 * -- rather than scanning tokens ad hoc -- is what makes the awkward cases come
9	 * out right, e.g. `--key -- --val 1` reporting "expected one argument" because
10	 * `--` classifies as '-' and a value-taking option's pattern only accepts 'A'.
11	 */
12	
13	import { HelpFormatter } from './help_formatter.mjs';
14	import { HelpAction, StoreAction, SUPPRESS } from './actions.mjs';
15	import { ArgumentError, SystemExit } from '../python/exceptions.mjs';
16	import { stderrWrite, stdoutWrite } from '../python/sys_io.mjs';
17	
18	/** `argparse`'s test for a token that merely looks like a negative number. */
19	const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;
20	
21	/** Messages keyed by nargs, as in `_match_argument`. */
22	const NARGS_ERRORS = {
23	  null: 'expected one argument',
24	  '?': 'expected at most one argument',
25	  '+': 'expected at least one argument',
26	};
