28	export class ArgumentParser {
29	  /**
30	   * @param {object} [options]
31	   * @param {string} [options.prog] program name used in usage/error text
32	   * @param {string} [options.prefixChars]
33	   * @param {boolean} [options.addHelp]
34	   * @param {boolean} [options.allowAbbrev]
35	   */
36	  constructor({ prog = undefined, prefixChars = '-', addHelp = true, allowAbbrev = true } = {}) {
37	    // CPython derives prog from `os.path.basename(sys.argv[0])`. The reference
38	    // build is a frozen executable, so its own name is what appears in usage
39	    // and error output -- including `--help`, which goes to stdout.
40	    this.prog = prog ?? 'test2_executable';
41	    this.prefixChars = prefixChars;
42	    this.allowAbbrev = allowAbbrev;
43	
44	    /** @type {import('./actions.mjs').Action[]} in definition order */
45	    this.actions = [];
46	    /** option string -> action */
47	    this.optionStringActions = Object.create(null);
48	
49	    if (addHelp) {
50	      this.addArgument(['-h', '--help'], {
51	        action: 'help',
52	        help: 'show this help message and exit',
53	      });
54	    }
55	  }
56	
57	  /**
58	   * Registers an argument. Mirrors `add_argument` for the option forms used
59	   * here.
60	   *
61	   * @param {string[]|string} optionStrings
62	   * @param {object} [spec]
63	   * @param {string} [spec.action] 'store' or 'help'
64	   * @param {boolean} [spec.required]
65	   * @param {string} [spec.help]
66	   * @param {string|null} [spec.metavar]
67	   * @param {((text: string) => *)|null} [spec.type]
68	   * @param {*} [spec.defaultValue]
69	   * @returns {import('./actions.mjs').Action}
70	   */
71	  addArgument(optionStrings, spec = {}) {
72	    const options = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
73	    // dest comes from the first long option, with the prefix stripped and
74	    // internal dashes turned into underscores.
75	    const longOption = options.find((option) => option.startsWith(this.prefixChars.repeat(2)));
76	    const source = longOption ?? options[0];
77	    const dest = source.replace(new RegExp(`^[${this.prefixChars}]+`), '').replace(/-/g, '_');
78	
79	    const common = {
80	      optionStrings: options,
81	      dest,
82	      required: spec.required ?? false,
83	      help: spec.help ?? '',
84	      metavar: spec.metavar ?? null,
85	      type: spec.type ?? null,
86	      defaultValue: spec.defaultValue ?? null,
87	    };
88	
89	    const action = spec.action === 'help' ? new HelpAction(common) : new StoreAction(common);
90	    this.actions.push(action);
91	    for (const option of options) this.optionStringActions[option] = action;
92	    return action;
93	  }
94	
95	  /** True when some option itself looks like a negative number. */
96	  get hasNegativeNumberOptionals() {
97	    return Object.keys(this.optionStringActions).some((option) => NEGATIVE_NUMBER_RE.test(option));
98	  }
