100	  /** @returns {HelpFormatter} */
101	  formatter() {
102	    return new HelpFormatter({ prog: this.prog });
103	  }
104	
105	  /** @returns {string} the usage block, one trailing newline */
106	  formatUsage() {
107	    const formatter = this.formatter();
108	    return HelpFormatter.finalize(formatter.formatUsage(this.actions));
109	  }
110	
111	  /** @returns {string} the complete help text */
112	  formatHelp() {
113	    const formatter = this.formatter();
114	    // Invocations are measured from inside the section, so the two-space group
115	    // indent counts toward the help column position.
116	    formatter.indent();
117	    for (const action of this.actions) formatter.addAction(action);
118	    formatter.dedent();
119	
120	    let text = formatter.formatUsage(this.actions);
121	    // Positionals come first, then the options group. An empty group renders
122	    // as nothing, so `positional arguments:` is absent here.
123	    const positionals = this.actions.filter((action) => action.optionStrings.length === 0);
124	    const optionals = this.actions.filter((action) => action.optionStrings.length > 0);
125	    text += formatter.formatSection('positional arguments', positionals);
126	    text += formatter.formatSection('options', optionals);
127	    return HelpFormatter.finalize(text);
128	  }
129	
130	  /** Writes usage to stderr. */
131	  printUsage(target = stderrWrite) {
132	    target(this.formatUsage());
133	  }
134	
135	  /** Writes full help to stdout. */
136	  printHelp() {
137	    stdoutWrite(this.formatHelp());
138	  }
