140	  /**
141	   * `parser.exit()` -- unwinds via SystemExit so callers can flush first.
142	   *
143	   * @param {number} [status]
144	   * @param {string|null} [message]
145	   * @returns {never}
146	   */
147	  exit(status = 0, message = null) {
148	    if (message) stderrWrite(message);
149	    throw new SystemExit(status);
150	  }
