152	  /**
153	   * `parser.error()` -- prints usage plus the message and exits 2.
154	   *
155	   * @param {string} message
156	   * @returns {never}
157	   */
158	  error(message) {
159	    this.printUsage(stderrWrite);
160	    this.exit(2, `${this.prog}: error: ${message}\n`);
161	  }
