163	  /**
164	   * `_get_action_name` -- how an action is named in the required-args message.
165	   *
166	   * @param {import('./actions.mjs').Action} action
167	   * @returns {string}
168	   */
169	  static actionName(action) {
170	    if (action.optionStrings.length > 0) return action.optionStrings.join('/');
171	    if (action.metavar !== null && action.metavar !== SUPPRESS) return action.metavar;
172	    return action.dest;
173	  }
