175	  /**
176	   * `_get_nargs_pattern` -- regex fragment describing what an action consumes.
177	   * Optionals drop the `-*` slack, which is why they refuse to reach across a
178	   * `--`.
179	   *
180	   * @param {import('./actions.mjs').Action} action
181	   * @returns {string}
182	   */
183	  static nargsPattern(action) {
184	    const { nargs } = action;
185	    let pattern;
186	    if (nargs === null || nargs === undefined) pattern = '(-*A-*)';
187	    else if (nargs === '?') pattern = '(-*A?-*)';
188	    else if (nargs === '*') pattern = '(-*[A-]*)';
189	    else if (nargs === '+') pattern = '(-*A[A-]*)';
190	    else if (nargs === 0) pattern = '(-*-*)';
191	    else pattern = `(-*${Array.from({ length: nargs }, () => 'A').join('-*')}-*)`;
192	
193	    if (action.optionStrings.length > 0) {
194	      pattern = pattern.split('-*').join('').split('-').join('');
195	    }
196	    return pattern;
197	  }
198	
199	  /**
200	   * `_match_argument` -- how many tokens this action takes from the pattern.
201	   *
202	   * @param {import('./actions.mjs').Action} action
203	   * @param {string} pattern
204	   * @returns {number}
205	   */
206	  matchArgument(action, pattern) {
207	    const regex = new RegExp(`^${ArgumentParser.nargsPattern(action)}`);
208	    const match = regex.exec(pattern);
209	    if (match === null) {
210	      const key = action.nargs === null || action.nargs === undefined ? 'null' : String(action.nargs);
211	      const message = NARGS_ERRORS[key] ?? `expected ${action.nargs} arguments`;
212	      throw new ArgumentError(ArgumentParser.actionName(action), message);
213	    }
214	    return match[1].length;
215	  }
216	
217	  /**
218	   * `_match_arguments_partial` -- greedily fit as many positionals as possible.
219	   *
220	   * @param {import('./actions.mjs').Action[]} actions
221	   * @param {string} pattern
222	   * @returns {number[]} token counts, one per matched action
223	   */
224	  static matchArgumentsPartial(actions, pattern) {
225	    for (let count = actions.length; count > 0; count -= 1) {
226	      const slice = actions.slice(0, count);
227	      const regex = new RegExp(`^${slice.map(ArgumentParser.nargsPattern).join('')}`);
228	      const match = regex.exec(pattern);
229	      if (match !== null) return match.slice(1).map((group) => group.length);
230	    }
231	    return [];
232	  }
233	
234	  /**
235	   * `_parse_optional` -- classify one token.
236	   *
237	   * @param {string} token
238	   * @returns {[import('./actions.mjs').Action|null, string, string|null, string|null]|null}
239	   *   null means "treat as positional"; an entry with a null action means
240	   *   "looks like an option but is unknown".
241	   */
242	  parseOptional(token) {
243	    if (token === '') return null;
244	    if (!this.prefixChars.includes(token[0])) return null;
245	
246	    const exact = this.optionStringActions[token];
247	    if (exact !== undefined) return [exact, token, null, null];
248	
249	    if (token.length === 1) return null;
250	
251	    const equals = token.indexOf('=');
252	    if (equals !== -1) {
253	      const head = token.slice(0, equals);
254	      const tail = token.slice(equals + 1);
255	      const action = this.optionStringActions[head];
256	      if (action !== undefined) return [action, head, '=', tail];
257	    }
258	
259	    const tuples = this.optionTuples(token);
260	    if (tuples.length > 1) {
261	      const matches = tuples.map((tuple) => tuple[1]).join(', ');
262	      this.error(`ambiguous option: ${token} could match ${matches}`);
263	    }
264	    if (tuples.length === 1) return tuples[0];
265	
266	    // A bare negative number is a value, not an unknown flag -- unless some
267	    // option is itself spelled like one.
268	    if (NEGATIVE_NUMBER_RE.test(token) && !this.hasNegativeNumberOptionals) return null;
269	    if (token.includes(' ')) return null;
270	
271	    return [null, token, null, null];
272	  }
273	
274	  /**
275	   * `_get_option_tuples` -- abbreviation matching for long options.
276	   *
277	   * @param {string} token
278	   * @returns {Array<[import('./actions.mjs').Action, string, string|null, string|null]>}
279	   */
280	  optionTuples(token) {
281	    const result = [];
282	    const chars = this.prefixChars;
283	    const isLong = chars.includes(token[0]) && token.length > 1 && chars.includes(token[1]);
284	
