286	      if (!this.allowAbbrev) return result;
287	      const equals = token.indexOf('=');
288	      const prefix = equals === -1 ? token : token.slice(0, equals);
289	      const explicit = equals === -1 ? null : token.slice(equals + 1);
290	      const sep = equals === -1 ? null : '=';
291	      for (const option of Object.keys(this.optionStringActions)) {
292	        if (option.startsWith(prefix)) {
293	          result.push([this.optionStringActions[option], option, sep, explicit]);
294	        }
295	      }
296	    } else if (chars.includes(token[0])) {
297	      // Short option, possibly with an attached value: -f or -fbar.
298	      const optionPrefix = token;
299	      const shortOption = token.slice(0, 2);
300	      const shortExplicit = token.slice(2);
301	      for (const option of Object.keys(this.optionStringActions)) {
