303	          result.push([this.optionStringActions[option], option, '', shortExplicit]);
304	        } else if (option.startsWith(optionPrefix)) {
305	          result.push([this.optionStringActions[option], option, null, null]);
306	        }
307	      }
308	    }
309	    return result;
310	  }
