/**
 * Argparse-surface fuzzer: compares /workspace/dataset/test2_executable against
 * /output/test2.mjs over a large generated battery of argv vectors.
 *
 * usage: node /tmp/fuzz.mjs [--only <substr>] [--jobs N]
 */
import { spawn } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

function normalize(text) {
  return String(text ?? '').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function run(cmd, argv, env, cwd) {
  return new Promise((resolve) => {
    const child = spawn(cmd, argv, {
      env: { ...process.env, ...(env || {}) },
      cwd: cwd || process.cwd(),
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => { out += d; });
    child.stderr.on('data', (d) => { err += d; });
