import { spawn } from 'node:child_process';
const REF = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';
const norm = (t) => String(t ?? '').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
function run(cmd, argv, env, cwd) {
  return new Promise((res) => {
    const c = spawn(cmd, argv, { env: { ...process.env, ...(env || {}) }, cwd: cwd || process.cwd(), stdio: ['ignore', 'pipe', 'pipe'] });
    let o = ''; let e = '';
    c.stdout.on('data', (d) => { o += d; });
    c.stderr.on('data', (d) => { e += d; });
    c.on('error', (x) => res({ stdout: '', stderr: 'ERR ' + x.message, status: null }));
    c.on('close', (s, g) => res({ stdout: o, stderr: g ? 'SIG:' + g : e, status: g ? 'SIG:' + g : s }));
  });
}
const cases = []; const seen = Object.create(null);
function add(argv, env, cwd) {
  const k = JSON.stringify([argv, env || null, cwd || null]);
  if (seen[k]) return; seen[k] = true; cases.push({ argv, env: env || null, cwd: cwd || null });
}

// homoglyph / non-ASCII option spellings
for (const t of ['--kéy', '--kеy', '--kéy', '－－key', '­-key', '–key', '—key',
  '−key', '--k​ey', '--KEY', '--Key', '--kEy', '--ｋｅｙ', '--k�ey'.replace('�', ''),
  '--key ', ' --key', '--vál', '--vａl']) {
  add([t, 'a', '--val', '1']);
  add([t, 'a']);
  add(['--key', 'a', '--val', '1', t]);
  add([`${t}=a`, '--val', '1']);
}

// tokens that contain a space (argparse treats as positional)
for (const t of ['--key a', '--key=a b', '-h h', '- h', '--val 1', ' --key', '--k a', '-- --',
  '--key a --val 1', '-1 5', '- ', '--bogus arg']) {
  add([t]);
  add([t, '--key', 'a', '--val', '1']);
  add(['--key', 'a', '--val', '1', t]);
  add(['--key', t, '--val', '1']);
}

// mixed abbreviation + equals + duplicates
const MIX = [
  ['--k=a', '--key=b', '--val', '1'],
  ['--key=b', '--k=a', '--val', '1'],
  ['--k', 'a', '--key', 'b', '--val', '1'],
  ['--v=1', '--val=2', '--key=a'],
  ['--val=2', '--v=1', '--key=a'],
  ['--k=a', '--v'],
  ['--v=1', '--k'],
  ['--k', '--v'],
  ['--k', '--v', '1'],
  ['--v', '--k', 'a'],
  ['--k=--v', '--v=--k'],
  ['--ke=a', '--val', '1', '--va', '2'],
  ['--key', 'a', '--val', '1', '--k', 'b'],
  ['--key', 'a', '--val', '1', '--v'],
  ['--h', '--key', 'a'],
  ['--key', 'a', '--h'],
  ['--he', '--val'],
  ['--key=a', '--val=1', '--he'],
];
for (const m of MIX) add(m);

// interspersed positionals in every gap of a 4-token command
const BASE = ['--key', 'a', '--val', '1'];
for (let i = 0; i <= BASE.length; i += 1) {
  for (const t of ['x', '-', '--', '-1', '-x', '', 'a b', '--bogus']) {
    const v = [...BASE]; v.splice(i, 0, t); add(v);
  }
}
// two positionals in every gap pair
for (let i = 0; i <= BASE.length; i += 1) {
  for (let j = i; j <= BASE.length; j += 1) {
    const v = [...BASE]; v.splice(j, 0, 'q'); v.splice(i, 0, 'p'); add(v);
  }
}

// -- placement in every gap
for (let i = 0; i <= BASE.length; i += 1) {
  const v = [...BASE]; v.splice(i, 0, '--'); add(v);
  const w = [...BASE]; w.splice(i, 0, '--', '--'); add(w);
}

// -h placement in every gap of an otherwise-broken command
for (const base of [['--key'], ['--bogus'], ['--key', 'a'], ['x'], ['--key', 'a', '--val', '1', 'x']]) {
  for (let i = 0; i <= base.length; i += 1) {
    const v = [...base]; v.splice(i, 0, '-h'); add(v);
    const w = [...base]; w.splice(i, 0, '--help'); add(w);
  }
}

