  'á', 'Á', 'K', 'ß', 'SS', 'İ', 'ı', '﻿a', 'a﻿']) {
  add(['--key', v, '--val', '1']);
  add([`--key=${v}`, '--val=1']);
}

// long option name / long value combos
add([`--key=${'a'.repeat(1000)}=${'b'.repeat(1000)}`, '--val', '1']);
add(['--key', `${'a'.repeat(500)} ${'b'.repeat(500)}`, '--val', '1']);
add([`--${'key'.repeat(100)}`, 'a', '--val', '1']);
add(['--key', 'a', '--val', '1', `--${'x'.repeat(1000)}`]);
add(['--key', 'a', '--val', '1', '-'.repeat(500)]);
add(['-'.repeat(500)]);
add(['-'.repeat(2), '-'.repeat(3)]);

// cwd variations
