  }
}
await Promise.all(Array.from({ length: JOBS }, worker));
const fails = results.filter((x) => !x.ok);
const clip = (s) => (s.length > 500 ? s.slice(0, 500) + '...' : s);
for (const f of fails) {
  console.log('FAIL argv=' + clip(JSON.stringify(f.argv)) + (f.env ? ' env=' + JSON.stringify(f.env) : '') + (f.cwd ? ' cwd=' + f.cwd : ''));
  console.log('  ref  ' + f.r.status + ' out=' + clip(JSON.stringify(f.r.stdout)) + ' err=' + clip(JSON.stringify(norm(f.r.stderr))));
  console.log('  port ' + f.p.status + ' out=' + clip(JSON.stringify(f.p.stdout)) + ' err=' + clip(JSON.stringify(norm(f.p.stderr))));
}
console.log(`\n${results.length - fails.length}/${results.length} identical (${fails.length} failures)`);
